assert('inpatient transfer is an authenticated server-authoritative workflow', inpatientTransferMigration.includes('CREATE OR REPLACE FUNCTION public.transfer_patient_ward_bed_workflow') && inpatientTransferMigration.includes('SECURITY DEFINER') && inpatientTransferMigration.includes("GRANT EXECUTE ON FUNCTION public.transfer_patient_ward_bed_workflow") && inpatientTransferMigration.includes("public.has_role(uid,'nurse')"), 'bed movement must execute through an explicit clinical workflow with server-side role validation');
