assert('bed movement creates a completed care-transition record and audit event', inpatientTransferMigration.includes("INSERT INTO public.care_transitions") && inpatientTransferMigration.includes("'completed'") && inpatientTransferMigration.includes("record_system_audit"), 'a completed physical movement must remain visible in continuity and audit history');
assert('Care Transitions uses the canonical movement RPC for transfers', careTransitions.includes("transfer_patient_ward_bed_workflow") && careTransitions.includes("_destination_bed_id:destinationBedId") && careTransitions.includes("_admission_id:activeAdmission.id"), 'transfer UI must not create a generic transition record without changing canonical bed state');
assert('Care Transitions derives the current bed and admission from protected workspaces', careTransitions.includes("get_admission_workspace") && careTransitions.includes("get_operational_workspace") && careTransitions.includes("sourceBed") && careTransitions.includes("activeAdmission"), 'movement UI must use server-authorized admission and ward-bed context');
assert('inpatient transfer rejects hidden duplicate occupied beds', inpatientTransferMigration.includes("patient_id = _patient_id") && inpatientTransferMigration.includes("status = 'occupied'") && inpatientTransferMigration.includes("Patient has multiple occupied ward beds"), 'movement must not create a second occupied bed when another occupied bed exists for the patient');
assert('legacy ward-bed assignment delegates to the canonical movement workflow', inpatientTransferMigration.includes('CREATE OR REPLACE FUNCTION public.assign_ward_bed') && inpatientTransferMigration.includes('RETURN public.transfer_patient_ward_bed_workflow(') && inpatientTransferMigration.includes('REVOKE ALL ON FUNCTION public.assign_ward_bed'), 'legacy assignment entry points must not bypass movement history and admission synchronization');
assert('legacy bed release cannot orphan an active admission', inpatientTransferMigration.includes('CREATE OR REPLACE FUNCTION public.release_ward_bed') && inpatientTransferMigration.includes('Active admitted patients must use the inpatient movement or discharge workflow') && inpatientTransferMigration.includes('REVOKE ALL ON FUNCTION public.release_ward_bed'), 'bed release must not clear an occupied bed while leaving an active admission without a canonical location');

assert('inpatient discharge owns occupied-bed cleanup', inpatientTransferMigration.includes('CREATE OR REPLACE FUNCTION public.discharge_admission_workflow') && inpatientTransferMigration.includes("status = 'discharged'") && inpatientTransferMigration.includes("status = 'cleaning'") && inpatientTransferMigration.includes('v_bed.id'), 'discharge must atomically transition the admission and its canonical occupied bed into the cleaning state');
